	('fff1167b-f88a-4ab7-91e4-996ffda558e7', '015d5b64-7fe7-40ef-8292-bcb823d27409', 'tpl-reading-input', 'lang-ja', '{"kind": "word", "word": "月曜日", "gloss": "Monday", "instruction": "Type the reading in kana"}', '{"primary": "げつようび", "accepted": ["げつようび"]}', '[]', '{"audio": "/audio/words/1255890.m4a", "image": "/images/vocab/1255890.svg", "wordAudio": "/audio/words/1255890.m4a"}', NULL, 1, 'system', 'published', '2026-08-26 00:30:30.844434', '2026-09-02 04:34:13.3775', NULL),
