	('fff9bae9-808f-48d6-b55e-bb633a50897d', '82228633-ef76-4487-9e4e-cda26a0fe9e0', 'tpl-mcq', 'lang-ja', '{"kind": "word", "word": "活動", "reading": "かつどう", "instruction": "What does this mean?"}', '{"primary": "activity (of a person, organization, animal, volcano, etc.)", "accepted": ["activity (of a person, organization, animal, volcano, etc.)"]}', '["to shine", "to grow", "member"]', '{"audio": "/audio/words/1208360.m4a", "wordAudio": "/audio/words/1208360.m4a"}', NULL, 1, 'system', 'published', '2026-08-26 05:54:45.243507', '2026-09-02 04:34:13.3775', NULL),
	('fffb2d54-9c74-46ec-8362-32c67a123be6', 'a50f4c2b-e1b0-44aa-92d7-ad905e9f49a9', 'tpl-dictation', 'lang-ja', '{"hint": "to assume an air of ...", "kind": "dictation", "introWord": "振る", "instruction": "Listen and type what you hear, in kana", "introReading": "ぶる"}', '{"primary": "ぶる", "accepted": ["ぶる", "振る"]}', '[]', '{"audio": "/audio/words/2038080.m4a", "wordAudio": "/audio/words/2038080.m4a"}', NULL, 1, 'system', 'published', '2026-08-30 02:18:24.985234', '2026-09-02 04:34:13.3775', NULL),
	('fffbb57a-1eeb-462a-8cc1-5fd59bd960e4', '32673840-0acc-4dc5-8cc2-3acbd4828448', 'tpl-reading-input', 'lang-ja', '{"kind": "word", "word": "基地", "gloss": "base (military, expedition, etc.)", "instruction": "Type the reading in kana"}', '{"primary": "きち", "accepted": ["きち"]}', '[]', '{"audio": "/audio/words/1219110.m4a", "wordAudio": "/audio/words/1219110.m4a"}', NULL, 1, 'system', 'published', '2026-08-26 05:54:52.546848', '2026-09-02 04:34:13.3775', NULL),
	('fffca03e-6555-45ae-b50f-43aac7ac536f', 'f6f7cb89-2c1a-4fbc-b67c-199adf972c73', 'tpl-listening', 'lang-ja', '{"kind": "listening", "introWord": "ふんだん", "instruction": "Listen. What does it mean?", "introReading": "ふんだん"}', '{"primary": "plentiful", "accepted": ["plentiful"]}', '["cheap", "implementation (e.g. of a system)", "mental arithmetic"]', '{"audio": "/audio/words/1011100.m4a", "wordAudio": "/audio/words/1011100.m4a"}', NULL, 1, 'system', 'published', '2026-08-30 02:18:24.985234', '2026-09-02 04:34:13.3775', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.particle_questions (id, set_id, sentence_id, blank_start, blank_end, answer, also_right, wrong, note, sort_index, created_at, updated_at) VALUES
	('pts-ja-de-location-q10', 'pts-ja-de-location', '5810f94e-698b-4bee-aa58-47a7a586d352', 2, 3, 'で', '{}', '{を,に,が}', 'The classroom is where the eating happens, so で.', 10, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-location-q4', 'pts-ja-de-location', 'bc388153-42e9-4cdb-ac75-efadce6ba86f', 2, 3, 'で', '{}', '{に,へ,が}', 'Eating happens in the park, so the park takes で. へ only points to a direction.', 4, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-location-q5', 'pts-ja-de-location', '027fad0d-dad8-4d97-9808-10d63697d7bf', 2, 3, 'で', '{}', '{を,が,へ}', 'The place where you work is marked with で. へ only points towards the bank.', 5, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-location-q6', 'pts-ja-de-location', '056726b8-61d6-4b46-8c97-60f6156409ce', 5, 6, 'で', '{}', '{を,が,へ}', 'で gives the place where the waiting goes on. The に after 七時 is for the time.', 6, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-location-q7', 'pts-ja-de-location', '313a9113-005f-44ea-bb88-ec56e001752b', 3, 4, 'で', '{}', '{が,と,へ}', 'で marks the point where the action of getting off happens.', 7, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-location-q8', 'pts-ja-de-location', 'e9f1c0c5-dd6a-4316-b923-e3fcdff1f22f', 5, 6, 'で', '{}', '{を,が,から}', 'で names the place where you will meet, as in "see you at the library".', 8, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-location-q9', 'pts-ja-de-location', '8651cdeb-911e-4a40-9fc6-655f9629c874', 2, 3, 'で', '{}', '{を,と,が}', 'で marks where you eat. ここを would make "here" the thing eaten.', 9, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-means-q10', 'pts-ja-de-means', 'c54a6fc8-1d9e-4be5-bc4d-aceea8bca167', 3, 4, 'で', '{から}', '{を,に,が}', 'で marks the material: a desk made of wood.', 10, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-means-q4', 'pts-ja-de-means', 'bd8eac84-4e38-46e9-9f48-9fa4f68daa65', 2, 3, 'で', '{}', '{を,に,へ}', 'で marks the bus as the means of getting there.', 4, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-means-q5', 'pts-ja-de-means', '2b01f877-0c60-4087-a85f-2cf8e5699ba1', 4, 5, 'で', '{}', '{を,が,と}', 'で names the transport. と would mean going together with a taxi.', 5, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-means-q7', 'pts-ja-de-means', '80407ef2-84e4-4109-b45d-09e4a2276d5f', 5, 6, 'で', '{}', '{を,に,と}', 'で marks the means of travel: by airplane.', 7, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-means-q8', 'pts-ja-de-means', 'dfdf38f5-5c04-4a0d-a55c-93fd6fdcb1c8', 3, 4, 'で', '{}', '{を,が,へ}', 'The subway is the means, so it takes で.', 8, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-means-q9', 'pts-ja-de-means', '5e339f41-2c84-45e7-ab2c-7fd544c1704c', 6, 7, 'で', '{から}', '{を,に,と}', 'で marks the material the cheese is made from.', 9, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-reason-q4', 'pts-ja-de-reason', 'be77a9ee-1bda-46f9-a97e-e2a516e6c232', 2, 3, 'で', '{}', '{を,に,と}', 'で links the headache to its cause: a cold.', 4, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-reason-q5', 'pts-ja-de-reason', '9f862e91-a1d2-47f3-843d-30cf4fd93de6', 2, 3, 'で', '{が,に}', '{を,と,へ}', 'で gives the homework as the reason for being busy.', 5, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-reason-q6', 'pts-ja-de-reason', '95f15617-edf6-467f-9a91-ac6e022a57ca', 4, 5, 'で', '{に}', '{を,と,へ}', 'で gives the cause of being tired: the long walk.', 6, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-tool-q4', 'pts-ja-de-tool', '3118a499-e6ad-476f-897a-75fc751b61b2', 8, 9, 'で', '{}', '{を,に,が}', 'で marks chopsticks as the tool for eating.', 4, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-tool-q5', 'pts-ja-de-tool', 'a0b80f6f-34d9-4f3b-b409-cbd47a660a15', 5, 6, 'で', '{}', '{を,に,と}', 'で marks the pen to write with. ボールペンに would mean writing on it.', 5, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-tool-q6', 'pts-ja-de-tool', 'b4ba442c-62a4-4759-b311-054eeb870b8a', 2, 3, 'で', '{}', '{を,に,が}', 'で marks the language used as the means of answering.', 6, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-tool-q8', 'pts-ja-de-tool', '911cdd8e-5fff-4162-9cec-45a90edd72aa', 5, 6, 'で', '{}', '{を,に,と}', 'で marks the language the class was carried out in.', 8, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-de-tool-q9', 'pts-ja-de-tool', '85953ab7-f146-4cf8-8bd3-be6d6ab045bb', 3, 4, 'で', '{}', '{を,に,と}', 'で marks the soap as what you wash with. 石けんを would make the soap the thing washed.', 9, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ga-desire-q0', 'pts-ja-ga-desire', 'd57425c8-7aa3-482a-85ca-0da8a15d9b81', 1, 2, 'が', '{を,は}', '{に,へ,と}', 'With たい, the thing you want to do it to is marked with が (を also works). に and へ do not mark that.', 0, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ga-desire-q1', 'pts-ja-ga-desire', '07939cf4-dc6e-42db-a45e-372a5c0773bd', 2, 3, 'が', '{は}', '{に,で,へ}', '欲しい is a feeling, and the thing wanted is marked with が. に and で do not fit.', 1, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ga-desire-q10', 'pts-ja-ga-desire', 'f24317b8-8fbf-4363-a56a-870ed60a9894', 3, 4, 'が', '{は}', '{に,で,から}', 'は gives the topic, me, and が marks what I like. On its own に cannot mark the thing liked.', 10, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ga-in-clause-q4', 'pts-ja-ga-in-clause', '963e3642-c3cf-4388-8246-8c62923c74d1', 4, 5, 'が', '{の}', '{を,は,へ}', 'Inside 私が生まれた, が marks who was born (の also works). は cannot sit inside a describing clause.', 4, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ga-in-clause-q5', 'pts-ja-ga-in-clause', 'f43931e0-fa95-499b-b686-417ecf0096b6', 4, 5, 'が', '{の}', '{を,へ,は}', 'The clause says who took the picture, and が marks that person (の also works). は cannot sit inside a describing clause.', 5, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ga-in-clause-q9', 'pts-ja-ga-in-clause', 'a091d7b4-dba3-47d3-a560-ad3101d94663', 2, 3, 'が', '{の}', '{を,へ,と}', 'が marks the class as what starts, inside the clause before の (の also works). 始まる takes no を.', 9, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ga-particle-q10', 'pts-ja-ga-particle', '4fb0896b-7536-403b-8ad4-594016d3846e', 1, 2, 'が', '{}', '{を,へ,から}', 'が marks who did it, the doer of the action. を would make the person the thing that was done.', 10, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ga-particle-q11', 'pts-ja-ga-particle', '0f6b58fd-9bb7-42f2-8143-2219288a7bd9', 1, 2, 'が', '{は}', '{を,に,へ}', 'が marks the sky as the thing that changed. 晴れる has no object, so を cannot be used.', 11, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ga-particle-q2', 'pts-ja-ga-particle', '99e7dc4e-0d92-4137-96a3-db4a5ff4f4ff', 1, 2, 'が', '{は}', '{と,に,へ}', 'The sore tooth is the subject of 痛い, so が marks it. に would point to a place or a time, not to what hurts.', 2, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ga-particle-q3', 'pts-ja-ga-particle', '6afde990-4fb7-4f1d-8814-1b3801afe779', 1, 2, 'が', '{は}', '{を,に,と}', 'が marks the part of the body that hurts. を would make the eyes an object, but nothing acts on them.', 3, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ga-particle-q4', 'pts-ja-ga-particle', '2db562e0-373f-4ce0-b944-534fd3938219', 1, 2, 'が', '{は}', '{を,に,から}', 'が marks the head as what hurts, new information. を cannot be used with 痛い.', 4, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ga-particle-q6', 'pts-ja-ga-particle', '4af1ec69-b798-4346-9170-345b4b976cf1', 1, 2, 'が', '{は}', '{を,で,に}', 'いる states that something exists, and が marks that something: an older brother.', 6, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ga-particle-q9', 'pts-ja-ga-particle', '1f7bf3ef-0d5c-4400-a4f5-9548931228c6', 1, 2, 'が', '{}', '{を,に,へ}', 'が marks the unknown thing that happened. を cannot mark the subject of あった.', 9, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-he-direction-q2', 'pts-ja-he-direction', '81e93716-5315-41b4-95e9-cc696525fdcf', 2, 3, 'へ', '{に}', '{が,で,と}', 'へ marks where you are told to head. で marks a place of action instead.', 2, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-he-direction-q3', 'pts-ja-he-direction', '9443d061-de44-46e6-bfac-6ed6232b0729', 2, 3, 'へ', '{に}', '{を,が,で}', 'へ marks the direction of travel, abroad.', 3, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-he-direction-q5', 'pts-ja-he-direction', '04c27889-99f4-46cc-988a-c226156b4f04', 6, 7, 'へ', '{に}', '{が,で,と}', 'へ marks the direction of travel to that place.', 5, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-he-direction-q6', 'pts-ja-he-direction', '1fa81129-3bfe-476e-8b2f-f04abdbbe780', 3, 4, 'へ', '{に}', '{が,を,と}', 'へ points the direction you must go: over there.', 6, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-he-direction-q7', 'pts-ja-he-direction', '5f201e2a-3a86-439c-817d-e12dd602e903', 1, 2, 'へ', '{に}', '{と,が,で}', 'へ marks the direction of the turn. で would mark where the turning happens, not which way.', 7, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-he-direction-q8', 'pts-ja-he-direction', 'f1da9e0a-c348-4646-92b9-0db7992ff929', 13, 14, 'へ', '{に}', '{が,で,と}', 'へ marks the kitchen as where Mary headed. で would be where something happens.', 8, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-he-direction-q9', 'pts-ja-he-direction', '45ac1004-4c37-464c-84f5-352590a0e26e', 1, 2, 'へ', '{に}', '{で,が,と}', 'へ marks the direction you want to move in: outside.', 9, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ka-or-q4', 'pts-ja-ka-or', '3c7167d7-bbe0-432b-8511-4b03c728eb82', 8, 9, 'か', '{}', '{を,が,に}', 'か offers two alternatives: markers or felt-tip pens.', 4, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ka-or-q5', 'pts-ja-ka-or', '59452ca3-db22-439f-bbbe-7c21e059475e', 6, 7, 'か', '{}', '{を,が,に}', 'The question "male or female?" puts か between the two choices.', 5, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-mo-particle-q1', 'pts-ja-mo-particle', 'd1dd6e5f-bd11-413b-ab29-48198bcd70cb', 1, 2, 'も', '{}', '{を,に,へ}', 'も means "also", so I join someone who is a teacher. に points to a place or a time instead.', 1, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-mo-particle-q6', 'pts-ja-mo-particle', '826d0d66-916e-47e5-84ca-78c5a27cd2e3', 1, 2, 'も', '{}', '{を,に,へ}', 'も means "so is my brother too". を cannot mark a person who is "like that".', 6, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ne-particle-q2', 'pts-ja-ne-particle', 'ab9d81a4-c226-456e-a718-ec8dadf136cc', 8, 9, 'ね', '{}', '{よ,か,が}', 'ね asks for agreement, matching "isn''t it?".', 2, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ne-particle-q4', 'pts-ja-ne-particle', 'f30ba673-07ad-4679-b066-c950d47bbd6b', 6, 7, 'ね', '{}', '{か,が,も}', 'ね makes small talk by seeking agreement: nice day, isn''t it?', 4, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ne-particle-q5', 'pts-ja-ne-particle', '7d4e81b4-1a9f-487b-9725-5505b214962e', 7, 8, 'ね', '{}', '{よ,は,へ}', 'ね fits "isn''t it?": you are checking the listener agrees. よ would be telling them.', 5, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ne-particle-q6', 'pts-ja-ne-particle', '64cfdb32-7761-4092-a040-b190384fc7b5', 7, 8, 'ね', '{}', '{か,を,と}', 'ね seeks agreement about something you both feel.', 6, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ne-particle-q7', 'pts-ja-ne-particle', 'fd4ac382-2a70-430d-8e75-6d11db929f36', 14, 15, 'ね', '{}', '{よ,か,が}', 'ね confirms what you already half know: "didn''t he?".', 7, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ne-particle-q8', 'pts-ja-ne-particle', '7c3b98fb-96a3-4118-809b-579eaa01a26d', 5, 6, 'ね', '{}', '{よ,が,を}', 'ね seeks agreement, "aren''t you?".', 8, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ne-particle-q9', 'pts-ja-ne-particle', '4b69a48f-149b-4dae-8edf-79ffc1bf1fe8', 21, 22, 'ね', '{}', '{よ,か,を}', 'ね checks something you half know: she did not go, did she?', 9, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-direction-q2', 'pts-ja-ni-direction', '4033867f-5343-493f-9e2e-0a05218f0811', 2, 3, 'に', '{へ}', '{が,と,で}', 'に names where you are told to go. で marks a place of action, not a destination.', 2, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-direction-q4', 'pts-ja-ni-direction', 'c718e4bd-3273-48a6-a79a-4a4329299652', 1, 2, 'に', '{へ}', '{を,が,と}', 'に marks the place you return to. が would make 家 the one doing the returning.', 4, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-direction-q8', 'pts-ja-ni-direction', 'd9332d66-0e36-49da-87bc-c3ba508ef097', 5, 6, 'に', '{へ}', '{を,が,と}', 'に marks the party as where you come to.', 8, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-direction-q9', 'pts-ja-ni-direction', 'd6fd79d6-54b2-4bf5-8000-56501c449306', 4, 5, 'に', '{へ}', '{を,が,と}', 'に marks the university you got into with 入る.', 9, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-existence-q0', 'pts-ja-ni-existence', '9a1192be-1d27-4a38-bb67-81d771a8b4d1', 6, 7, 'に', '{}', '{で,を,へ}', 'に marks where something is. で is for where an action happens.', 0, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-existence-q1', 'pts-ja-ni-existence', '1413d58e-53bc-45f5-81b8-6edafb7e93c1', 5, 6, 'に', '{}', '{で,を,と}', 'に marks where the cat is. で would need an action.', 1, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-existence-q2', 'pts-ja-ni-existence', '34c078fe-879e-407a-95b4-bbf5a1461a95', 4, 5, 'に', '{}', '{で,を,へ}', 'に marks where a living thing is, with いる.', 2, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-existence-q3', 'pts-ja-ni-existence', '5332ccc8-8fa6-402f-8663-7ea7bce59f34', 5, 6, 'に', '{}', '{で,を,と}', 'に marks where someone is. で would suggest an action at the door.', 3, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-existence-q4', 'pts-ja-ni-existence', '447f4893-d80e-4cbc-8ad7-f3a775f3c4e0', 5, 6, 'に', '{}', '{で,を,へ}', 'に marks where the bank is. ある here is existence, not an action.', 4, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-existence-q5', 'pts-ja-ni-existence', '0fa0071c-f365-4631-a581-db5a94644166', 4, 5, 'に', '{}', '{で,を,と}', 'に marks the place where the cinema might be.', 5, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-existence-q6', 'pts-ja-ni-existence', '8033091d-3eaa-47d2-af9c-d7d2bc25fe8f', 3, 4, 'に', '{}', '{から,を,へ}', 'に marks where the schools are; は just makes the town the topic.', 6, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-existence-q7', 'pts-ja-ni-existence', '3b0fd3b2-2637-431a-b8ae-384a7c818f10', 3, 4, 'に', '{}', '{で,を,と}', 'に marks the shop as where the postcards are.', 7, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-existence-q8', 'pts-ja-ni-existence', 'cba2dfc6-d964-4fd9-ba74-42c254c7d0fe', 6, 7, 'に', '{}', '{で,を,へ}', 'に marks where the cat is.', 8, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-existence-q9', 'pts-ja-ni-existence', 'b98fd2fd-59fb-4244-b8a4-d3b341d4c06a', 3, 4, 'に', '{}', '{から,へ,と}', 'に marks the house as where the rooms are; は just makes the house the topic.', 9, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-purpose-q1', 'pts-ja-ni-purpose', 'a70e75e5-a003-4469-8627-dcae2b60fcd9', 6, 7, 'に', '{へ}', '{で,を,が}', 'A noun like 買い物 plus に says the purpose of going: shopping.', 1, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-purpose-q2', 'pts-ja-ni-purpose', '74b2f1b1-bbd6-4d1c-af14-60b6c9c5c384', 5, 6, 'に', '{へ}', '{で,が,の}', '買い物に行く means go in order to shop.', 2, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-purpose-q3', 'pts-ja-ni-purpose', 'bfeb09aa-aa0b-46db-aeca-00cbe5c4d464', 12, 13, 'に', '{へ}', '{で,が,と}', '買い物 plus に gives the purpose of the trip. The earlier へ is the direction.', 3, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-purpose-q4', 'pts-ja-ni-purpose', '2b78bdd1-39fd-465f-a299-4b5569d33585', 2, 3, 'に', '{へ}', '{で,を,の}', 'に marks the trip as the purpose of going. 旅行で would mean on a trip, not going in order to travel.', 4, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-purpose-q5', 'pts-ja-ni-purpose', '4b69a48f-149b-4dae-8edf-79ffc1bf1fe8', 11, 12, 'に', '{へ}', '{を,が,と}', 'に marks the trip as the purpose of going.', 5, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-purpose-q6', 'pts-ja-ni-purpose', '45b392cc-5c17-466b-9e24-c69b9fef483a', 12, 13, 'に', '{へ}', '{で,を,と}', 'スキー plus に says what the family goes to do.', 6, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-ni-purpose-q7', 'pts-ja-ni-purpose', '9e929a6b-bc1b-4504-b374-c15de17ba495', 9, 10, 'に', '{へ}', '{を,が,と}', 'The second に gives the purpose: go skiing. The first に is the time.', 7, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-no-possessive-q6', 'pts-ja-no-possessive', '1f8b1bd8-4504-40e7-b9fa-d25dbe8fc5f4', 5, 6, 'の', '{}', '{が,を,へ}', 'の marks Pochi as the owner of the food.', 6, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-no-possessive-q7', 'pts-ja-no-possessive', '8e12e9e7-ab78-43cc-98ae-90cb30eeef54', 4, 5, 'の', '{}', '{が,に,を}', '誰の asks whose: の links owner to car.', 7, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-no-possessive-q8', 'pts-ja-no-possessive', 'a7e8ea94-18b2-4ccf-ace5-e409260d102e', 2, 3, 'の', '{}', '{を,に,で}', 'の links 今日 to 新聞: today''s paper.', 8, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-no-possessive-q9', 'pts-ja-no-possessive', 'acf88f81-2451-495e-b3a1-a0ca367aea85', 3, 4, 'の', '{}', '{を,に,で}', 'の links the rabbit to its ears.', 9, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-no-pronoun-q4', 'pts-ja-no-pronoun', '38a0523a-c92b-4560-80ec-e317d2a6eca9', 5, 6, 'の', '{}', '{に,と,か}', 'の is the pronoun "one" here: the yellow one. に would need an actual noun before it.', 4, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-no-pronoun-q5', 'pts-ja-no-pronoun', '404590b0-93c4-46d1-b00c-c7d921ec10e8', 7, 8, 'の', '{}', '{に,で,と}', 'の stands for coffee, already understood: the hot one. で and に cannot take the place of a noun.', 5, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-no-pronoun-q6', 'pts-ja-no-pronoun', '0b4b7e15-1ea5-491c-adf3-90ed1dfe9b0a', 7, 8, 'の', '{}', '{を,へ,か}', '薄いの means the weak one, with の replacing the noun. へ and か do not do that.', 6, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-no-pronoun-q7', 'pts-ja-no-pronoun', 'bc74d908-43fd-4f53-b450-26baafa8634b', 4, 5, 'の', '{}', '{を,に,で}', 'あの黒いの means "that black one". を, に and で cannot replace the noun after an adjective.', 7, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-no-pronoun-q8', 'pts-ja-no-pronoun', 'fbc289af-80d5-4327-8602-48d735b7e236', 6, 7, 'の', '{}', '{を,に,と}', 'の stands for the thing I bought, so 買ったの is "the one I bought". を and に cannot replace that noun.', 8, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-to-quotation-q5', 'pts-ja-to-quotation', 'f3b2bbab-326a-4531-8361-892908c024cd', 6, 7, 'と', '{}', '{を,が,に}', 'と closes the quoted order 止まれ.', 5, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-to-quotation-q9', 'pts-ja-to-quotation', '30d76a5e-b65f-4176-b86d-f79f48dd222c', 14, 15, 'と', '{}', '{か,が,に}', 'と closes the quote before the speaker and 言った.', 9, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-to-together-n5-q5', 'pts-ja-to-together-n5', 'a70e75e5-a003-4469-8627-dcae2b60fcd9', 2, 3, 'と', '{}', '{を,が,で}', 'と marks who you went shopping with.', 5, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-to-together-n5-q6', 'pts-ja-to-together-n5', '41cea107-708b-4f65-b6bf-d0cb892fd9c5', 1, 2, 'と', '{}', '{が,を,で}', '誰と asks who you go with. 誰が would ask who goes, not who goes with you.', 6, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-to-together-n5-q7', 'pts-ja-to-together-n5', '6dee65fa-7c14-4934-816c-6ba70492690b', 1, 2, 'と', '{}', '{を,が,で}', 'と goes with いっしょに to mean together with me.', 7, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-to-together-n5-q8', 'pts-ja-to-together-n5', '8db73f92-52f4-4cf3-9fd8-c39faadaca4c', 1, 2, 'と', '{に}', '{を,が,へ}', 'と marks the person you walk beside.', 8, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-to-together-n5-q9', 'pts-ja-to-together-n5', '8733d2fe-ddc0-4de2-9a03-38cf2b5a5728', 1, 2, 'と', '{}', '{を,が,へ}', 'と pairs with いっしょに: come together with me.', 9, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-to-with-q4', 'pts-ja-to-with', 'bc3b22a2-a43b-43e9-8635-a4e740f95b87', 3, 4, 'と', '{や}', '{か,を,も}', 'と links the two things that exist: a sauna and a pool.', 4, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-to-with-q5', 'pts-ja-to-with', 'eb27e5e3-fe1e-4840-a0c1-eb6c66b44e0d', 3, 4, 'と', '{や}', '{か,が,で}', 'と joins notebook and pen as one set of things to take out.', 5, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-to-with-q6', 'pts-ja-to-with', '46c3f6ba-0b4a-4a27-85e0-64375024bb50', 1, 2, 'と', '{や}', '{も,が,へ}', 'と joins face and hands: wash both.', 6, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-to-with-q7', 'pts-ja-to-with', '39935723-ede4-45c5-9728-daf47e3d0b84', 1, 2, 'と', '{}', '{を,で,や}', 'と chains the family members into one complete list. や would make them mere examples.', 7, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-to-with-q8', 'pts-ja-to-with', 'b8ef2ee4-7ce6-4b1c-abf0-b5eebe55533c', 5, 6, 'と', '{を}', '{が,で,へ}', 'と marks the companion you walk with. 犬が would make the dog the walker.', 8, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-to-with-q9', 'pts-ja-to-with', 'b4ad6347-2fa6-4a43-a27a-8d208836985f', 4, 5, 'と', '{に}', '{を,が,へ}', 'と marks who Ken ran alongside.', 9, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-wa-particle-q0', 'pts-ja-wa-particle', 'dd2ce160-2d59-42c4-82fa-29ae42039ad6', 1, 2, 'は', '{が}', '{の,で,に}', 'は marks what the sentence is about: "as for me". の would turn it into "my doctor", which is not what the English says.', 0, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-wa-particle-q1', 'pts-ja-wa-particle', '491c3e6f-ced3-49e3-83cf-a4fd3841ae41', 1, 2, 'は', '{が}', '{の,と,から}', 'は sets up the topic, my father, and then says something about him. の would link 父 to 医者 as the doctor of my father.', 1, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-wa-particle-q10', 'pts-ja-wa-particle', 'c9774609-ceb6-4c78-9dbe-e015f53d281b', 1, 2, 'は', '{が}', '{を,へ,から}', 'は marks the snow as the topic, and the verb says what happened to it. を would make the snow the object.', 10, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-wa-particle-q2', 'pts-ja-wa-particle', '13b9c04e-ec40-4ed3-bc5b-5d04c6bd40ec', 1, 2, 'は', '{が}', '{を,に,へ}', 'は names the topic and the rest describes it. 青い is a description, so it cannot take を.', 2, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-wa-particle-q3', 'pts-ja-wa-particle', 'ec706901-e934-4500-a048-dfeb715246f6', 1, 2, 'は', '{が}', '{か,から,と}', 'は gives a general statement about birds as a topic. と would mean "fly with birds", which is not the English.', 3, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-wa-particle-q4', 'pts-ja-wa-particle', '5d610614-3995-417d-abe0-7dbc1886f9e0', 2, 3, 'は', '{が}', '{の,に,へ}', 'これは introduces the thing and then names it. に points to a place or a time, not to what something is.', 4, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-wa-particle-q6', 'pts-ja-wa-particle', '4823b670-0698-463f-950d-8cf876fb08cb', 3, 4, 'は', '{が}', '{を,と,の}', 'は marks the dog as the topic of the description. 大きい describes, so を does not fit.', 6, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-wa-particle-q7', 'pts-ja-wa-particle', '68a52700-3251-4f24-9984-53da46e9caf2', 3, 4, 'は', '{が}', '{の,と,に}', 'は picks あなた as the topic of the question. の would ask about "your student", a different person.', 7, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-wa-particle-q8', 'pts-ja-wa-particle', 'b1c3e190-f52c-4faf-b4b8-8df145cace5e', 2, 3, 'は', '{が}', '{を,で,と}', 'は makes 今日 the topic: "as for today". で would mean "by" or "at", which breaks 暑い.', 8, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-wa-particle-q9', 'pts-ja-wa-particle', 'eced6125-cbf9-47e7-a4c9-fded28be7fe1', 1, 2, 'は', '{が}', '{の,へ,から}', 'は sets outside as the topic and 暗い describes it. から would mean "from outside", which 暗い cannot take here.', 9, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-wo-object-q1', 'pts-ja-wo-object', 'e52c2589-d71d-4d98-a098-81c07fa9e6ad', 4, 5, 'を', '{は}', '{が,に,と}', 'を marks the thing you look at.', 1, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-wo-object-q2', 'pts-ja-wo-object', '2b31a26b-66de-4c9c-b7d1-b76706391a71', 5, 6, 'を', '{は}', '{が,に,と}', 'を marks what was bought.', 2, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-wo-object-q3', 'pts-ja-wo-object', '642c98b9-0177-4139-af60-06a66432a2dc', 4, 5, 'を', '{}', '{が,に,で}', 'を marks the shoes put on. が would make the shoes the doer.', 3, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-wo-object-q4', 'pts-ja-wo-object', '07ae9e62-f1f7-4461-9c96-48d1aedbcf86', 4, 5, 'を', '{は}', '{が,で,と}', 'を marks the building you are told to look at.', 4, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-wo-object-q5', 'pts-ja-wo-object', '1f6c1386-d969-4475-991f-49a737ac325b', 3, 4, 'を', '{が,は}', '{に,で,と}', 'を marks the song being sung. With a can-verb, が also works, and は makes the song the topic.', 5, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-wo-object-q6', 'pts-ja-wo-object', 'b817c5c8-6018-483a-bc7c-e70d78240993', 6, 7, 'を', '{は}', '{が,に,で}', 'を marks the thing worn.', 6, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-wo-object-q7', 'pts-ja-wo-object', '9a13bd32-6196-47f1-9d84-f05f4307d691', 5, 6, 'を', '{は}', '{が,に,と}', 'を marks what we will listen to.', 7, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-wo-object-q8', 'pts-ja-wo-object', 'd21bd40c-77ea-493b-9e1b-82e3f8662527', 2, 3, 'を', '{は}', '{が,に,と}', 'を marks the tea being made.', 8, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-wo-object-q9', 'pts-ja-wo-object', '52d82935-bbb8-4452-9cdc-60831e690394', 3, 4, 'を', '{}', '{が,に,で}', 'を marks the sugar to pass.', 9, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-yo-particle-q4', 'pts-ja-yo-particle', '9cf2e232-f8f6-4d1f-ad9c-ce9486ad3719', 8, 9, 'よ', '{}', '{ね,か,が}', 'よ announces news the listener did not know: the medicine is ready. ね would ask for agreement.', 4, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-yo-particle-q5', 'pts-ja-yo-particle', 'afcda098-1183-4079-87af-193fc36b622e', 12, 13, 'よ', '{}', '{ね,は,を}', 'ほら points something out, and よ tells the listener the news.', 5, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-yo-particle-q6', 'pts-ja-yo-particle', '6ddbfe22-66af-45ca-93cc-32a460532db7', 7, 8, 'よ', '{}', '{ね,か,を}', 'よ announces that dinner is ready. ね would ask for agreement instead.', 6, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-yo-particle-q7', 'pts-ja-yo-particle', '7afce6ae-ec73-4de1-9cb9-0db03d2c9873', 5, 6, 'よ', '{}', '{ね,か,が}', 'よ reassures the listener: no problem, I tell you.', 7, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-yo-particle-q8', 'pts-ja-yo-particle', 'b0b7b087-995b-488b-806a-9948e0f0bb74', 6, 7, 'よ', '{}', '{ね,が,も}', 'よ states your decision to the listener: keep the change.', 8, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754'),
	('pts-ja-yo-particle-q9', 'pts-ja-yo-particle', '2b03cf5d-7cc0-4607-b4a7-cccba2e7cec5', 10, 11, 'よ', '{}', '{ね,か,を}', 'よ tells the listener something they cannot see themselves. ね would ask them to agree about their own tie.', 9, '2026-10-20 11:42:39.944754', '2026-10-20 11:42:39.944754') ON CONFLICT DO NOTHING;
